<?php
require dirname(__DIR__).'/bootstrap.php';requireRole('admin');
$role=(($_GET['role']??'student')==='teacher')?'teacher':'student';$pageTitle=$role==='teacher'?'Teachers':'Students';$dashboardMode=true;$errors=[];$userModel=new User();$search=trim((string)($_GET['search']??''));$perPage=10;$totalUsers=$userModel->countByRole($role,$search);$totalPages=max(1,(int)ceil($totalUsers/$perPage));$page=max(1,min($totalPages,(int)($_GET['page']??1)));
if($_SERVER['REQUEST_METHOD']==='POST'){
    postOnly();$action=(string)($_POST['action']??'');
    if($action==='create'){$v=(new Validator())->required($_POST,'name','Name')->length($_POST,'name','Name',2,120)->required($_POST,'email','Email')->email($_POST,'email')->required($_POST,'password','Password')->length($_POST,'password','Password',10,200);if($userModel->findByEmail((string)($_POST['email']??'')))$v->add('email','This email is already registered.');if(!$v->passes())$errors=$v->errors();else{try{$id=$userModel->create(trim((string)$_POST['name']),trim((string)$_POST['email']),(string)$_POST['password'],$role);audit($role.'_created','users',$id);Session::flash('success',ucfirst($role).' account created.');redirectTo('admin/users.php?role='.$role);}catch(Throwable $e){error_log($e->getMessage());$errors=['form'=>'Account could not be created. Check the email and try again.'];}}}
    if($action==='status'){$id=(int)($_POST['user_id']??0);$status=($_POST['status']??'')==='disabled'?'disabled':'active';if($id>0){$userModel->updateStatus($id,$status);audit('user_status_'.$status,'users',$id);Session::flash('success','Account status updated.');redirectTo('admin/users.php?role='.$role);}}
}
$users=$userModel->listByRole($role,$search,$perPage,($page-1)*$perPage);$classes=(new ClassModel())->all();$pdo=Database::connection();
require APP_ROOT.'/components/header.php';
?>
<div class="page-heading"><div><h1><?= e($pageTitle) ?></h1><p>Create <?= e($role) ?> accounts and manage access to Examly.</p></div></div>
<div class="content-columns"><section class="panel"><div class="panel-header"><h2><?= e($pageTitle) ?> directory</h2><span class="badge badge-blue"><?= count($users) ?> accounts</span></div><div class="panel-body">
    <form method="get" class="filter-bar" style="margin:0 0 16px;padding:0;border:0"><input type="hidden" name="role" value="<?= e($role) ?>"><div class="field"><label for="search">Search by name or email</label><input id="search" name="search" value="<?= e($search) ?>" placeholder="Search accounts"></div><button class="button button-outline button-small">Search</button></form>
    <div class="table-wrap"><table><thead><tr><th>Name</th><th>Class</th><th>Status</th><th>Joined</th><th>Access</th></tr></thead><tbody>
    <?php foreach($users as $person): ?><tr><td><strong><?= e($person['name']) ?></strong><br><span class="text-small muted"><?= e($person['email']) ?></span></td><td><?php $cs=Database::connection()->prepare('SELECT c.class_name,c.section FROM class_students x JOIN classes c ON c.id=x.class_id WHERE x.student_id=? ORDER BY c.class_name'); if($role==='student'){$cs->execute([$person['id']]);echo e(implode(', ',array_map(fn($x)=>$x['class_name'].' '.$x['section'],$cs->fetchAll()))?:'—');}else echo '—'; ?></td><td><span class="badge <?= $person['status']==='active'?'badge-green':'badge-red' ?>"><?= e(ucfirst($person['status'])) ?></span></td><td><?= dateTime($person['created_at'],'M j, Y') ?></td><td><form method="post" class="inline-form"><?= CSRF::field() ?><input type="hidden" name="action" value="status"><input type="hidden" name="user_id" value="<?= (int)$person['id'] ?>"><input type="hidden" name="status" value="<?= $person['status']==='active'?'disabled':'active' ?>"><button class="button button-outline button-small" type="submit"><?= $person['status']==='active'?'Disable':'Enable' ?></button></form></td></tr><?php endforeach; ?>
    <?php if(!$users): ?><tr><td colspan="5"><div class="empty-state"><strong>No <?= e($role) ?> accounts found</strong>Use the form to add one.</div></td></tr><?php endif; ?>
    </tbody></table></div><?php $paginationPath='admin/users.php';$paginationParams=['role'=>$role];if($search!=='')$paginationParams['search']=$search;require APP_ROOT.'/components/pagination.php'; ?>
</div></section><aside class="panel"><div class="panel-header"><h2>Add <?= e($role) ?></h2></div><div class="panel-body">
    <?php if($errors): ?><ul class="error-list"><?php foreach($errors as $error): ?><li><?= e($error) ?></li><?php endforeach; ?></ul><?php endif; ?>
    <form method="post" class="form-stack"><?= CSRF::field() ?><input type="hidden" name="action" value="create"><div class="field"><label for="name">Full name</label><input id="name" name="name" required minlength="2" maxlength="120" value="<?= old('name') ?>"></div><div class="field"><label for="email">Email</label><input id="email" name="email" type="email" required maxlength="190" value="<?= old('email') ?>"></div><div class="field"><label for="password">Temporary password</label><input id="password" name="password" type="password" required minlength="10" maxlength="200"><span class="field-help">Share this securely and ask the user to change it after sign-in.</span></div><button class="button button-primary" type="submit">Create <?= e($role) ?> account</button></form>
</div></aside></div>
